  "GET /api/config/get": (request, res) => {
    const { type } = request.query;
    let parameters = {
      ifLogin: true,
      status: true,
      message: "成功",
      code: 0,
      ifAdmin: false,
      content: [],
    };
    if (type == 4) {
      parameters.content = [
        {
          modeName: "成绩分析",
          eModeName: "Grade Analysis",
          modeValue: [
            {
              showSwitch: "open",
              showName: "班级成绩概况",
              name: "studentScore",
              eName: "Grade Overview",
              sort: 1,
            },
            {
              showSwitch: "open",
              showName: "成绩分段对比",
              name: "analyseRank",
              eName: "Grade Comparison",
              sort: 2,
            },
            {
              showSwitch: "open",
              showName: "学情分层对比",
              name: "analyseScoreSection",
              eName: "Learning Level Comparison",
              sort: 3,
            },
          ],
          modeKey: "scoreSection",
        },
        {
          modeName: "试题分析",
          eModeName: "Question Analysis",
          modeValue: [
            {
              showSwitch: "open",
              showName: "小题班级对比",
              name: "groupQuestion",
              eName: "Question Analysis",
              sort: 1,
            },
            {
              showSwitch: "open",
              showName: "知识点分析",
              name: "knowledgePoint",
              eName: "Knowledge Point Analysis",
              sort: 2,
            },
          ],
          modeKey: "questionSection",
        },
        {
          modeName: "学生分析",
          eModeName: "Student Analysis",
          modeValue: [
            {
              showSwitch: "open",
              showName: "学生得分",
              name: "studentScore",
              eName: "Student Grade",
              sort: 1,
            },
          ],
          modeKey: "studentSection",
        },
        {
          modeName: "学生分组",
          eModeName: "Student Group",
          modeValue: [
            {
              showSwitch: "open",
              showName: "学生分组",
              name: "studentGroup",
              eName: "Student Group",
              sort: 2,
            },
          ],
          modeKey: "studentGroup",
        },
        {
          modeName: "逐题分析",
          eModeName: "Item Analysis",

          modeValue: [
            {
              showSwitch: "open",
              showName: "课堂讲评题目",
              name: "classEvaluation",
              eName: "Classroom Review Question Title",
              sort: 1,
            },
          ],
          modeKey: "questionAnalysis",
        },
      ];
    } else if (type == 6) {
      parameters.content = {
        allSubjectScoreParentSwitch: true,
        parentScoreWatchSwitch: true,
        parentScoreAndRankWatchSwitch: true,
        studentScoreWatchSwitch: true,
        allSubjectScoreStudentSwitch: true,
        studentScoreAndRankWatchSwitch: false,
        examSummaryDefaultNew: true,
        examSummaryDefaultOld: false,
        examAlias: true,
      };
    } else if (type == 8) {
      parameters.content = null;
    } else if (type == 10) {
      parameters.content = [3, 5, 6];
    } else {
      parameters.content = {
        advanceCount: 1,
        retreatCount: 1,
        frontCount: 1,
        backCount: 1,
        scoreStart: 69,
        scoreEnd: 72,
      };
    }
    res.send(parameters);
  },
