export const mockDelayMs = 1000;

export const routes = fromRouteMap(mockData).map((route) => ({
  ...route,
  handler:
    typeof route.handler === "function"
      ? async ({ query, body, headers }) => {
          let result;
          const response = {
            end: (buffer) => {
              result = binary(buffer, response.headers);
            },
            headers: {},
            send: (data) => {
              result = json(data);
            },
            setHeader: (key, value) => {
              response.headers[key] = value;
            },
          };
          const returnedResult = await route.handler(
            { query, body, headers },
            response,
          );
          return returnedResult || result;
        }
      : json(route.handler),
}));
